import { ProcessDefinition, AppNode, Edge, Swimlane } from '../../types';
import { FormatAdapter, ImportResult, ExportResult } from './types';

type JsonMap = Record<string, any>;
type EditorCondition = { path: number; expression: string; priority?: number; label?: string; description?: string; target?: string | number };

const ENGINE_TO_EDITOR: Record<string, string> = {
  blankStartEvent: 'BlankStartEvent',
  messageStartEvent: 'MessageStartEvent',
  signalStartEvent: 'SignalStartEvent',
  timerStartEvent: 'TimerStartEvent',
  conditionalStartEvent: 'ConditionalStartEvent',
  blankEndEvent: 'BlankEndEvent',
  errorEndEvent: 'ErrorEndEvent',
  messageEndEvent: 'MessageEndEvent',
  signalEndEvent: 'SignalEndEvent',
  escalationEndEvent: 'EscalationEndEvent',
  terminationEndEvent: 'TerminateEndEvent',
  compensationEndEvent: 'CompensationEndEvent',
  scriptTask: 'ScriptTask',
  externalTask: 'ServiceTaskREST',
  userTask: 'UserTask',
  rulesTask: 'ServiceTaskRules',
  callActivity: 'CallActivity',
  manualTask: 'ManualTask',
  sendTask: 'SendTask',
  receiveTask: 'ReceiveTask',
  parallelGateway: 'ParallelGateway',
  exclusiveGateway: 'XorGateway',
  inclusiveGateway: 'InclusiveGateway',
  eventBasedGateway: 'EventBasedGateway',
  intermediateTimerEvent: 'IntermediateCatchTimerEvent',
  intermediateCatchTimerEvent: 'IntermediateCatchTimerEvent',
  intermediateCatchMessageEvent: 'IntermediateCatchMessageEvent',
  intermediateCatchSignalEvent: 'IntermediateCatchSignalEvent',
  intermediateCatchConditionalEvent: 'IntermediateCatchConditionalEvent',
  intermediateCatchLinkEvent: 'IntermediateCatchLinkEvent',
  intermediateThrowMessageEvent: 'IntermediateThrowMessageEvent',
  intermediateThrowSignalEvent: 'IntermediateThrowSignalEvent',
  intermediateThrowErrorEvent: 'IntermediateThrowErrorEvent',
  intermediateThrowEscalationEvent: 'IntermediateThrowEscalationEvent',
  intermediateThrowLinkEvent: 'IntermediateThrowLinkEvent',
  intermediateThrowCompensationEvent: 'IntermediateThrowCompensationEvent',
  timerBoundaryEvent: 'TimerBoundaryEvent',
  messageBoundaryEvent: 'MessageBoundaryEvent',
  signalBoundaryEvent: 'SignalBoundaryEvent',
  conditionalBoundaryEvent: 'ConditionalBoundaryEvent',
  compensationBoundaryEvent: 'CompensationBoundaryEvent',
  errorBoundaryEvent: 'ErrorBoundaryEvent',
  escalationBoundaryEvent: 'EscalationBoundaryEvent',
  nonInterruptingTimerBoundaryEvent: 'NonInterruptingTimerBoundaryEvent',
  nonInterruptingMessageBoundaryEvent: 'NonInterruptingMessageBoundaryEvent',
  nonInterruptingSignalBoundaryEvent: 'NonInterruptingSignalBoundaryEvent',
  nonInterruptingConditionalBoundaryEvent: 'NonInterruptingConditionalBoundaryEvent',
};

const EDITOR_TO_ENGINE: Record<string, string> = Object.fromEntries(
  Object.entries(ENGINE_TO_EDITOR).map(([engine, editor]) => [editor, engine])
);

Object.assign(EDITOR_TO_ENGINE, {
  FormStartEvent: 'blankStartEvent',
  TerminateEndEvent: 'terminationEndEvent',
  ServiceTaskREST: 'externalTask',
  ServiceTaskLLM: 'externalTask',
  ServiceTaskEmail: 'externalTask',
  ServiceTaskSMS: 'externalTask',
  ServiceTaskDB: 'externalTask',
  ServiceTaskMCP: 'externalTask',
  ServiceTaskRules: 'rulesTask',
  SubProcess: 'SubProcess',
});

const SERVICE_TOPICS: Record<string, string> = {
  ServiceTaskREST: 'rest',
  ServiceTaskLLM: 'ai',
  ServiceTaskEmail: 'email',
  ServiceTaskSMS: 'sms',
  ServiceTaskDB: 'database',
  ServiceTaskMCP: 'mcp',
};

const EVENT_NODE_SIZE = 56;
const GATEWAY_NODE_SIZE = 72;
const TASK_NODE_WIDTH = 180;
const TASK_NODE_HEIGHT = 72;

function normalizeKey(key: string): string {
  return key ? key.charAt(0).toLowerCase() + key.slice(1) : key;
}

function normalizeKeys(value: any): any {
  if (Array.isArray(value)) return value.map(normalizeKeys);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value).map(([k, v]) => [normalizeKey(k), normalizeKeys(v)]));
}

function compact<T extends JsonMap>(value: T): T {
  return Object.fromEntries(
    Object.entries(value).filter(([, v]) => v !== undefined && v !== null && v !== '' && !(Array.isArray(v) && v.length === 0))
  ) as T;
}

function asArray<T>(value: T[] | undefined): T[] {
  return Array.isArray(value) ? value : [];
}

function labelFrom(node: JsonMap): string {
  return node.label || node.name || node.key || String(node.id);
}

function nodePosition(index: number): { x: number; y: number } {
  return { x: 120 + (index % 8) * 220, y: 120 + Math.floor(index / 8) * 140 };
}

function nodeDimensions(type: string): { width: number; height: number } {
  if (type.endsWith('Gateway')) return { width: GATEWAY_NODE_SIZE, height: GATEWAY_NODE_SIZE };
  if (type.endsWith('Event')) return { width: EVENT_NODE_SIZE, height: EVENT_NODE_SIZE };
  return { width: TASK_NODE_WIDTH, height: TASK_NODE_HEIGHT };
}

function messageName(message: any): string | undefined {
  if (typeof message === 'string') return message;
  return message?.name || message?.staticText;
}

function timerDefinition(timer: any): string | undefined {
  if (typeof timer === 'string') return timer;
  if (timer?.durationMs) return `PT${Math.max(1, Math.round(Number(timer.durationMs) / 1000))}S`;
  return timer?.cronExpression || timer?.period;
}

function extensionByTopic(node: JsonMap): string {
  const topic = node.properties?.topic;
  switch (topic) {
    case 'ai':
    case 'llm':
      return 'ServiceTaskLLM';
    case 'email':
    case 'mail':
      return 'ServiceTaskEmail';
    case 'sms':
      return 'ServiceTaskSMS';
    case 'database':
    case 'db':
    case 'sql':
      return 'ServiceTaskDB';
    case 'mcp':
      return 'ServiceTaskMCP';
    default:
      return 'ServiceTaskREST';
  }
}

function editorTypeFor(node: JsonMap): string {
  const rawType = node.type;
  if (rawType === 'externalTask') return extensionByTopic(node);
  return ENGINE_TO_EDITOR[rawType] || rawType;
}

function importNode(node: JsonMap, index: number, actorTypeByNode: Map<string, string>): AppNode {
  const type = editorTypeFor(node);
  const attachedTo = node.activity ?? node.attachedTo;
  const conditions = conditionsFromBpjs(node);
  const data = compact({
    label: labelFrom(node),
    description: node.description,
    isMerging: node.isMerging,
    script: node.script,
    resultVariable: node.resultVariable || node.properties?.resultVariable,
    outputVariable: node.properties?.outputVariable,
    dmnName: node.dmnName,
    returnVariable: node.returnVariable,
    processName: typeof node.processName === 'string' ? node.processName : node.processName?.name,
    keepBusinessKey: node.keepBusinessKey,
    asAsyncCall: node.asAsyncCall,
    sequentialLoop: node.sequentialLoop,
    collectionName: node.collectionName,
    elementName: node.elementName,
    messageName: messageName(node.message),
    signalName: node.signal,
    timerDefinition: timerDefinition(node.timer),
    condition: node.condition || node.properties?.condition,
    linkName: node.linkName || node.name,
    errorMessage: node.errorMessage || node.message,
    errorPayload: node.errorObject || node.error,
    escalationName: node.escalation,
    exceptionType: node.exceptionType,
    actorType: node.properties?.actorType || actorTypeByNode.get(String(node.id)),
    conditions,
    endpoint: node.properties?.endpoint,
    method: node.properties?.method,
    retries: node.properties?.retries,
    connectionId: node.properties?.connectorId || node.properties?.extensions?.connectionId,
    queryType: node.properties?.extensions?.queryType,
    query: node.properties?.extensions?.query,
    parameters: node.properties?.extensions?.params,
    model: node.properties?.extensions?.model,
    systemPrompt: node.properties?.extensions?.systemPrompt,
    userPrompt: node.properties?.extensions?.prompt,
    fromEmail: node.properties?.extensions?.fromEmail,
    to: node.properties?.extensions?.to,
    subject: node.properties?.extensions?.subject,
    body: node.properties?.extensions?.body,
    isHtml: node.properties?.extensions?.isHtml,
    cancelActivity: !String(node.type).startsWith('nonInterrupting'),
    properties: node.properties,
    __bpjs: node,
  });

  return {
    id: String(node.id),
    type,
    position: node.position || nodePosition(index),
    parentNode: attachedTo !== undefined && attachedTo !== null ? String(attachedTo) : undefined,
    extent: attachedTo !== undefined && attachedTo !== null ? 'parent' : undefined,
    data,
    ...nodeDimensions(type),
  };
}

function conditionsFromBpjs(node: JsonMap): EditorCondition[] | undefined {
  const expressions = node.expressions && typeof node.expressions === 'object' ? node.expressions : {};
  const conditions: EditorCondition[] = Object.entries(expressions).map(([target, expression], index) => ({
    path: index,
    target: numericIfPossible(target),
    expression: String(expression),
    label: target,
  }));
  if (node.defaultPath !== undefined && node.defaultPath !== null) {
    conditions.push({
      path: conditions.length,
      target: node.defaultPath,
      expression: '',
      label: 'default',
    });
  }
  return conditions.length > 0 ? conditions : undefined;
}

function importEdge(conn: JsonMap, index: number, nodeById: Map<string, JsonMap>): Edge {
  const source = nodeById.get(String(conn.from));
  const sourceHandle = sourceHandleForConnection(source, conn.to);
  return {
    id: String(conn.id || `e_${conn.from}_${conn.to}_${index}`),
    source: String(conn.from),
    target: String(conn.to),
    sourceHandle: conn.sourceHandle ?? sourceHandle,
    targetHandle: conn.targetHandle,
    data: compact({
      isRecursive: conn.isRecursive,
      isDefault: conn.isDefault,
      __bpjs: conn,
    }),
  };
}

function sourceHandleForConnection(source: JsonMap | undefined, target: any): string | undefined {
  if (!source) return undefined;
  const conditions = conditionsFromBpjs(source);
  const match = conditions?.find(condition => String(condition.target) === String(target));
  return match ? String(match.path) : undefined;
}

function processFromBpjs(process: JsonMap, processIndex: number): ProcessDefinition {
  const rawNodes = asArray<JsonMap>(process.nodes);
  const actorTypeByNode = laneActorMap(asArray<JsonMap>(process.lanes));
  const nodeById = new Map(rawNodes.map(node => [String(node.id), node]));
  const nodes = rawNodes.map((node, index) => importNode(node, index, actorTypeByNode));
  const swimlanes = importLanes(asArray<JsonMap>(process.lanes));
  return {
    id: String(process.id || `process_${processIndex + 1}`),
    name: process.name || `Process ${processIndex + 1}`,
    description: process.description,
    isSubProcess: process.isSubProcess,
    nodes,
    edges: asArray<JsonMap>(process.connections).map((conn, index) => importEdge(conn, index, nodeById)),
    swimlanes,
  };
}

function laneActorMap(lanes: JsonMap[]): Map<string, string> {
  const map = new Map<string, string>();
  for (const lane of lanes) {
    const actorType = lane.actorType || lane.name || lane.key;
    if (!actorType) continue;
    for (const nodeId of asArray(lane.nodes || lane.nodeIds || lane.flowNodeRefs || lane.flowNodes)) {
      let ref: unknown = nodeId;
      if (nodeId && typeof nodeId === 'object') {
        const nodeRef = nodeId as JsonMap;
        ref = nodeRef.id || nodeRef.nodeId || nodeRef.flowNodeRef;
      }
      if (ref !== undefined && ref !== null) map.set(String(ref), actorType);
    }
  }
  return map;
}

function importLanes(lanes: JsonMap[]): Swimlane[] {
  return lanes.map((lane, index) => ({
    id: String(lane.id || lane.key || lane.name || `lane_${index + 1}`),
    name: lane.actorType || lane.name || lane.key || `Lane ${index + 1}`,
    x: lane.x ?? 40,
    y: lane.y ?? 60 + index * 160,
    width: lane.width ?? 1600,
    height: lane.height ?? 140,
    color: lane.color,
  }));
}

function messageFromData(data: JsonMap): JsonMap | undefined {
  if (!data.messageName && !data.messagePayload && !data.messagePayloadVariableName) return undefined;
  return compact({
    name: data.messageName,
    staticText: data.messageName,
    payloadVariableName: data.messagePayloadVariableName,
    variableName: data.messageVariableName,
    variableContent: data.messagePayload,
  });
}

function timerFromData(data: JsonMap): JsonMap | undefined {
  const def = data.timerDefinition || data.timerDate;
  if (!def) return undefined;
  if (typeof def === 'string' && /^PT\d+S$/i.test(def)) {
    return { durationMs: Number(def.replace(/^PT/i, '').replace(/S$/i, '')) * 1000 };
  }
  return data.timerType === 'date' ? { date: data.timerDate } : { period: def };
}

function exportProperties(type: string, data: JsonMap): JsonMap {
  const topic = SERVICE_TOPICS[type] || data.properties?.topic;
  const properties = compact({
    ...data.properties,
    actorType: data.actorType,
    resultVariable: data.resultVariable || data.outputVariable,
    topic,
    connectorId: data.connectorId || data.connectionId,
    endpoint: data.endpoint,
    method: data.method,
    retries: data.retries,
    execution: data.execution,
    extensions: compact({
      ...(data.properties?.extensions || {}),
      headers: data.headers,
      requestBody: data.requestBody,
      bearerToken: data.bearerToken,
      apiKey: data.apiKey,
      connectionId: data.connectionId,
      queryType: data.queryType,
      query: data.query,
      params: data.parameters,
      model: data.model,
      prompt: data.userPrompt,
      systemPrompt: data.systemPrompt,
      fromEmail: data.fromEmail,
      to: data.to,
      cc: data.cc,
      bcc: data.bcc,
      subject: data.subject,
      body: data.body,
      isHtml: data.isHtml,
      attachments: data.attachments,
      mcpServerUrl: data.mcpServerUrl,
      mcpServerName: data.mcpServerName,
      mcpOperation: data.mcpOperation,
      mcpToolName: data.mcpToolName,
      mcpToolArguments: data.mcpToolArguments,
      mcpResourceUri: data.mcpResourceUri,
      mcpPromptName: data.mcpPromptName,
      mcpPromptArguments: data.mcpPromptArguments,
    }),
  });

  if (Object.keys(properties.extensions || {}).length === 0) delete properties.extensions;
  return properties;
}

function exportNode(node: AppNode): JsonMap {
  const data = node.data || {};
  const original = data.__bpjs || {};
  const type = data.__bpjs?.type || EDITOR_TO_ENGINE[node.type || ''] || node.type || 'externalTask';
  const out: JsonMap = compact({
    ...original,
    id: numericIfPossible(node.id),
    key: data.key || data.__bpjs?.key || node.id,
    type,
    label: data.label,
    description: data.description,
    position: node.position,
    properties: exportProperties(node.type || '', data),
    script: data.script,
    resultVariable: data.resultVariable || data.outputVariable,
    dmnName: data.dmnName || data.decisionFile,
    returnVariable: data.returnVariable || data.resultVariable,
    processName: data.processName ? { name: data.processName } : undefined,
    keepBusinessKey: data.keepBusinessKey,
    asAsyncCall: data.asAsyncCall,
    sequentialLoop: data.sequentialLoop,
    collectionName: data.collectionName,
    elementName: data.elementName,
    message: messageFromData(data),
    signal: data.signalName,
    timer: timerFromData(data),
    condition: data.condition,
    linkName: data.linkName,
    errorMessage: data.errorMessage || data.exceptionType,
    errorObject: data.errorPayload,
    escalation: data.escalationName,
    isMerging: data.isMerging,
    expressions: expressionsFromData(data),
    defaultPath: defaultPathFromData(data),
    activity: node.parentNode ? numericIfPossible(node.parentNode) : undefined,
  });

  if (Object.keys(out.properties || {}).length === 0) delete out.properties;
  return out;
}

function expressionsFromData(data: JsonMap): JsonMap | undefined {
  const conditions = asArray<JsonMap>(data.conditions);
  if (conditions.length === 0) return undefined;
  return Object.fromEntries(
    conditions
      .filter(condition => condition.expression && condition.target)
      .map(condition => [String(condition.target), condition.expression])
  );
}

function defaultPathFromData(data: JsonMap): string | number | undefined {
  return asArray<JsonMap>(data.conditions).find(condition => !condition.expression)?.target;
}

function numericIfPossible(value: string): string | number {
  return /^-?\d+$/.test(value) ? Number(value) : value;
}

function exportConnection(edge: Edge): JsonMap {
  const original = edge.data?.__bpjs || {};
  return compact({
    ...original,
    id: edge.id,
    from: numericIfPossible(edge.source),
    to: numericIfPossible(edge.target),
    sourceHandle: edge.sourceHandle,
    targetHandle: edge.targetHandle,
  });
}

function exportLanes(swimlanes: Swimlane[] | undefined, nodes: AppNode[]): JsonMap[] {
  return asArray(swimlanes).map(lane => ({
    id: lane.id,
    name: lane.name,
    actorType: lane.name,
    nodes: nodes.filter(node => node.data?.actorType === lane.name).map(node => numericIfPossible(node.id)),
    x: lane.x,
    y: lane.y,
    width: lane.width,
    height: lane.height,
    color: lane.color,
  }));
}

function exportProcesses(processes: ProcessDefinition[]): JsonMap[] {
  return processes.map(process => compact({
    id: process.id,
    name: process.name,
    description: process.description,
    isSubProcess: process.isSubProcess,
    nodes: process.nodes.map(exportNode),
    connections: process.edges.map(exportConnection),
    lanes: exportLanes(process.swimlanes, process.nodes),
  }));
}

function parseBpjs(content: string): JsonMap {
  return normalizeKeys(JSON.parse(content));
}

export const bpjsAdapter: FormatAdapter = {
  id: 'bpjs',
  name: 'Chronicle BPJS',
  fileExtensions: ['.bpjs', '.json'],
  isJson: true,

  detect(content: string, fileName?: string): boolean {
    if (fileName?.toLowerCase().endsWith('.bpjs')) return true;
    try {
      const data = parseBpjs(content);
      return Array.isArray(data.processes) || Array.isArray(data.nodes);
    } catch {
      return false;
    }
  },

  import(content: string): ImportResult {
    const data = parseBpjs(content);
    const rawProcesses = Array.isArray(data.processes) ? data.processes : [data];
    return {
      processes: rawProcesses.map(processFromBpjs),
      warnings: [],
    };
  },

  export(processes: ProcessDefinition[], projectName: string): ExportResult {
    const payload = {
      format: 'bpjs',
      name: projectName,
      version: 1,
      processes: exportProcesses(processes),
    };
    return {
      content: `${JSON.stringify(payload, null, 2)}\n`,
      extension: '.bpjs',
      mimeType: 'application/json',
    };
  },
};
